// Unified API response helpers
// Standard: { sucess: boolean, data: any, msg: string }

export function ok(res, data = {}, msg = "Success", status = 200) {
  return res.status(status).json({ sucess: true, data, msg });
}

export function created(res, data = {}, msg = "Created") {
  return ok(res, data, msg, 201);
}

export function fail(res, msg = "Failed", status = 400, data = {}) {
  return res.status(status).json({ sucess: false, data, msg });
}

export function serverError(res, msg = "Server error", error) {
  const data = error ? { error: process.env.NODE_ENV === "development" ? String(error.stack || error) : String(error.message || error) } : {};
  return res.status(500).json({ sucess: false, data, msg });
}
